cmnf5wmcf000juxs3fmyo13c5	cmnf5wccs0003uxs3mc5evhul	class Animal { void sound() { print("Some sound"); } } class Dog extends Animal { void\nsound() { print("Bark"); } } Animal a = new Dog(); a.sound(); // Prints "Bark" —\nruntime polymorphism\nHere, even though a is declared as type Animal, it calls Dog's sound() method at runtime. This is the\nessence of dynamic dispatch.\nQ7. What is type coercion? Explain with an example.\nType coercion (also called implicit type conversion) is the automatic conversion of a value from one\ndata type to another by the compiler or runtime system, without the programmer explicitly requesting\nit. It occurs when an operator or function requires a certain type but receives a different compatible\ntype.\nType coercion differs from explicit type casting, where the programmer manually specifies the\nconversion. Coercion is done automatically and can sometimes lead to unexpected results or subtle\nbugs.\nExample in C:\nint x = 5; float y = 2.5; float result = x + y; // x is coerced from int to float	[0.0045819283,0.0060857325,0.005079265,-0.07268417,-0.032453787,0.012387816,0.0141418725,0.011028037,0.018861907,-0.00934421,0.00859452,-0.0123649305,-0.010680355,0.0006593572,0.14185579,0.0027466253,-0.025961779,-0.008026759,0.020287301,-0.023632336,0.013262585,-0.0074478053,0.0011985203,-0.018693877,0.0022913483,-0.0058014807,0.012026445,-0.002643457,0.033948448,-0.0021392824,-0.02192736,0.026197191,0.012340099,0.018021677,-0.016653601,0.00077911286,-0.0053057377,0.0017418922,0.011037437,0.008149285,-0.0102759525,0.007566112,-0.0016876177,0.013524674,-0.0015775961,0.017000524,0.0049304026,-0.021192808,-0.034871385,0.017406642,-0.004935016,0.00020668971,0.0012523648,-0.19657464,-0.002181895,3.858316e-05,0.00242108,0.0103150625,0.011924817,0.0069727497,0.013420891,0.014271564,-0.0008147549,-0.0018550691,0.019448249,-0.008124701,0.026997078,0.009515076,-0.018410293,-0.0014828561,0.020839559,0.0032278693,-0.0016586678,-0.019519798,0.010165379,-0